"use client";import {useState} from 'react';export default function ChallengeSubmit({challengeId}:{challengeId:string}){const[flag,setFlag]=useState(''),[msg,setMsg]=useState(''),[busy,setBusy]=useState(false);async function submit(e:React.FormEvent){e.preventDefault();setBusy(true);try{const r=await fetch('/api/challenges/submit',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({challengeId,flag})});const data=await r.json();setMsg(data.message||data.error||'Tidak ada respons')}catch{setMsg('Koneksi gagal')}finally{setBusy(false)}}return <form onSubmit={submit} className="mt-5"><label>Submit flag</label><input required placeholder="CTF{...}" value={flag} onChange={e=>setFlag(e.target.value)}/><button disabled={busy} className="mt-3">{busy?'Memeriksa...':'Kirim Flag'}</button><p className="mt-3">{msg}</p></form>}